package tn.esprit.raghd_selmi_4act.service.impl;

import jakarta.persistence.EntityNotFoundException;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import tn.esprit.raghd_selmi_4act.entities.Paiement;
import tn.esprit.raghd_selmi_4act.repository.PaiementRepository;
import tn.esprit.raghd_selmi_4act.service.interfaces.IPaiementService;

import java.util.List;

@Service
@RequiredArgsConstructor
public class PaiementServiceImpl implements IPaiementService {

    // Injected by Spring (constructor injection, generated by Lombok)
    private final PaiementRepository repository;

    @Override
    public List<Paiement> retrieveAllPaiements() {
        return repository.findAll();
    }

    @Override
    public Paiement retrievePaiement(Long id) {
        return repository.findById(id)
                .orElseThrow(() -> new EntityNotFoundException("Paiement not found with id " + id));
    }

    @Override
    public Paiement addPaiement(Paiement entity) {
        return repository.save(entity);
    }

    @Override
    public Paiement modifyPaiement(Paiement entity) {
        return repository.save(entity);
    }

    @Override
    public void removePaiement(Long id) {
        repository.deleteById(id);
    }
}
